import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';

function TrainDetails() {
  const { train_number } = useParams();
  const [trainData, setTrainData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchTrainRoute = async () => {
      try {
        const response = await fetch(`https://cors-anywhere.herokuapp.com/https://rappid.in/apis/train.php?train_no=${train_number}`);
        if (!response.success) {
          throw new Error('Network response was not ok');
        }
        const result = await response.json();
        const { success, data } = result;
        console.log(success);
        if (success) {
          setTrainData(data);
        } else {
          throw new Error('Failed to fetch train data');
        }
        setLoading(false);
      } catch (error) {
        setError(error);
        setLoading(false);
      }
    };

    fetchTrainRoute();
  }, [train_number]);

  if (loading) {
    return <p>Loading...</p>;
  }

  if (error) {
    return <p>Error: {error.message}</p>;
  }

  return (
    <div>
      <h1>Train Details for Train Number: {train_number}</h1>
      {trainData}
    </div>
  );
}

export default TrainDetails;
